insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-catalog-asks-relayed-2026-11-16','fact','Sam''s Credential Catalog asks, relayed by COBIx (#3405)','Sam, 2026-11-16, 9:56 to 9:58 AM PT, relayed by COBIx on #3405: move the Statewide and CPL-AI figures up with the metric boxes; collapse the header and photos, the Worth a faculty review strip and each field group, with the review cards short (title and issuer) until clicked; a Clear all filters link beside the chips; and chips on unreviewed credentials for good local course alignments.',array['credential-catalog','library','sam'],'proposed','COBIx relay on #3405 of Sam''s asks, 2026-11-16',null,null,'S669',date '2026-11-16'),
('d-catalog-header-folds-s669','decision','Credential Catalog: figures in the header, folds, Clear all filters (#3406)','S669, #3406 (e37c1841): the two recommendation figures are .kpi boxes that still filter; the intro, photos and Start with start closed; review cards show title and issuer until opened; field groups fold, open by default; fold state is layout in localStorage cpl_catalog_folds, filters never; Clear all filters shows whenever atDefault() is false. First card row at 691px on a 768px-tall window.',array['credential-catalog','library','decision'],'proposed','S669; #3406',null,null,'S669',date '2026-11-16'),
('d-cplai-title-chips-s669','decision','CPL-AI chips on not-yet-evaluated credentials: 16, by folded title and issuer (#3407)','S669, #3407 (257ff645): a not-yet-evaluated row joins a frozen CPL-AI certification by norm_title, the issuer agreeing by whole words (CPL_AI_ISSUER). 16 of COBIx''s 17 take a chip; Certiport''s Swift Associate row is held out. The chip names one course (the scoped college''s best, else the best example plus the other-college count), with the evidence word and caveat. No chip from CIP alone.',array['credential-catalog','cpl-ai','decision'],'proposed','S669; #3407 and COBIx''s review',null,null,'S669',date '2026-11-16'),
('p-title-keyed-join-leaks-across-rows-s669','pitfall','A join keyed by title lights every row that shares the title','S669, COBIx on #3407: cpl_ai_title_matches first returned {title: certs}, so a same-titled row from another issuer, or an exhibit or held row sharing the title, took the badge. Key a per-row check by the row (an id set), and match an issuer by whole words from an explicit map, never a code prefix as a substring (aws against Amazon Web Services).',array['credential-catalog','cpl-ai','pitfall'],'proposed','S669; COBIx on #3407',null,null,'S669',date '2026-11-16')
